    # Pattern to match {{ name | filter | ... }}
    pattern = r'\{\{\s*([^}]+?)\s*\}\}'

    def lookup_path(context: Mapping[str, Any], path: str) -> Any:
        """Look up a dotted path in the context."""
        parts = path.split('.')
        current = context
        for part in parts:
            if not isinstance(current, Mapping):
                raise KeyError(f"Cannot index non-mapping value with '{part}'")
            if part not in current:
                raise KeyError(part)
            current = current[part]
        return current

    def apply_filter(value: str, filter_name: str) -> str:
        """Apply a filter to a string value."""
        if filter_name == 'upper':
            return value.upper()
        elif filter_name == 'lower':
            return value.lower()
        elif filter_name == 'title':
            return value.title()
        elif filter_name == 'trim':
            return value.strip()
        else:
            raise ValueError(f"Unknown filter: {filter_name}")

    def replace_placeholder(match: re.Match) -> str:
        """Replace a single placeholder with its rendered value."""
        content = match.group(1).strip()
        parts = [p.strip() for p in content.split('|')]

        path = parts[0]
        filters = parts[1:]

        # Look up the value
        value = lookup_path(context, path)

        # Convert to string: None -> "", others -> str(value)
        if value is None:
            result = ""
        else:
            result = str(value)

        # Apply filters left to right
        for filter_name in filters:
            result = apply_filter(result, filter_name)

        return result

    return re.sub(pattern, replace_placeholder, template)"}}

