from typing import List, Tuple


def extract_headings(markdown: str) -> List[Tuple[int, str]]:
    result: List[Tuple[int, str]] = []
    lines = markdown.splitlines()

    in_fence = False
    fence_char = None

    for line in lines:
        leading_spaces = len(line) - len(line.lstrip(' '))
        if leading_spaces <= 3:
            stripped_start = line.lstrip(' ')
            if stripped_start.startswith('```'):
                if not in_fence:
                    in_fence = True
                    fence_char = '`'
                elif fence_char == '`':
                    in_fence = False
                    fence_char = None
                continue
            elif stripped_start.startswith('~~~'):
                if not in_fence:
                    in_fence = True
                    fence_char = '~'
                elif fence_char == '~':
                    in_fence = False
                    fence_char = None
                continue

        if in_fence:
            continue

        if leading_spaces > 3:
            continue

        stripped = line.lstrip(' ')

        if not stripped.startswith('#'):
            continue

        hash_count = 0
        for ch in stripped:
            if ch == '#':
                hash_count += 1
            else:
                break

        if hash_count < 1 or hash_count > 6:
            continue

        rest = stripped[hash_count:]

        if rest == '':
            result.append((hash_count, ''))
            continue

        if rest[0] not in ' \t':
            continue

        title = rest.lstrip(' \t')

        title_stripped = title.rstrip()
        if title_stripped.endswith('#'):
            idx = len(title_stripped) - 1
            while idx >= 0 and title_stripped[idx] == '#':
                idx -= 1
            if idx < len(title_stripped) - 1 and (idx < 0 or title_stripped[idx] in ' \t'):
                title = title_stripped[:idx+1].rstrip()

        result.append((hash_count, title))

    return result
