    result: List[Tuple[int, str]] = []
    lines = markdown.splitlines()

    in_fence = False
    fence_char = None

    for line in lines:
        leading_spaces = len(line) - len(line.lstrip(' '))
        if leading_spaces <= 3:
            stripped_start = line.lstrip(' ')
